using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Collections.Generic;

namespace ConfigApi
{
    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();
            var app = builder.Build();
            app.UseRouting();
            app.MapControllers();
            app.Run();
        }
    }

    // Global configuration store - shared mutable state
    public static class GlobalConfig
    {
        public static JsonObject Settings { get; set; } = new JsonObject
        {
            ["theme"] = "default",
            ["locale"] = "en-US",
            ["debug"] = false
        };
    }

    [Microsoft.AspNetCore.Mvc.Route("api/[controller]")]
    [Microsoft.AspNetCore.Mvc.ApiController]
    public class SettingsController : Microsoft.AspNetCore.Mvc.ControllerBase
    {
        // GET /api/settings - returns current config as JSON
        [Microsoft.AspNetCore.Mvc.HttpGet]
        public Microsoft.AspNetCore.Mvc.IActionResult GetSettings()
        {
            return new Microsoft.AspNetCore.Mvc.OkObjectResult(GlobalConfig.Settings);
        }

        // PATCH /api/settings - deep merge user input into global config
        [Microsoft.AspNetCore.Mvc.HttpPatch]
        public Microsoft.AspNetCore.Mvc.IActionResult PatchSettings(
            [Microsoft.AspNetCore.Mvc.FromBody] JsonObject patch)
        {
            if (patch == null)
                return new Microsoft.AspNetCore.Mvc.BadRequestResult();

            DeepMerge(GlobalConfig.Settings, patch);
            return new Microsoft.AspNetCore.Mvc.OkObjectResult(GlobalConfig.Settings);
        }

        // Recursive deep merge - NO key filtering
        private void DeepMerge(JsonObject target, JsonObject source)
        {
            foreach (var kvp in source)
            {
                var key = kvp.Key;
                var sourceValue = kvp.Value;

                if (sourceValue is JsonObject sourceObj)
                {
                    if (target[key] is JsonObject targetObj)
                    {
                        DeepMerge(targetObj, sourceObj);
                    }
                    else
                    {
                        target[key] = sourceObj.Deserialize<JsonObject>();
                    }
                }
                else
                {
                    // Directly assigns ANY key including __proto__, constructor, etc.
                    target[key] = sourceValue?.DeepClone();
                }
            }
        }
    }

    // Renders a dashboard page using config values
    [Microsoft.AspNetCore.Mvc.Route("dashboard")]
    public class DashboardController : Microsoft.AspNetCore.Mvc.ControllerBase
    {
        [Microsoft.AspNetCore.Mvc.HttpGet]
        public Microsoft.AspNetCore.Mvc.IActionResult Index()
        {
            var config = GlobalConfig.Settings;
            // If attacker injects "scriptTag" key via prototype pollution,
            // it gets rendered directly into HTML
            var customScript = config["customScript"]?.ToString() ?? "";
            var theme = config["theme"]?.ToString() ?? "default";
            var locale = config["locale"]?.ToString() ?? "en-US";

            var html = $@"
<!DOCTYPE html>
<html>
<head>
    <title>Dashboard</title>
    <meta charset='utf-8'>
</head>
<body>
    <h1>Dashboard - Theme: {theme}, Locale: {locale}</h1>
    <div id='content'>Loading...</div>
    {customScript}
    <script src='/static/dashboard.js'></script>
</body>
</html>";

            return new Microsoft.AspNetCore.Mvc.ContentResult
            {
                Content = html,
                ContentType = "text/html",
                StatusCode = 200
            };
        }
    }
}
